 $('#chats').querySelectorAll('[data-chat]').forEach(b=>b.onclick=safe(()=>selectChat(b.dataset.chat)));
 const scroller=$('#messages-scroll'),bottom=scroller.scrollHeight-scroller.scrollTop-scroller.clientHeight<130;
