 const summaries=new Map((state.summaries||[]).map(s=>[s.through_id,s]));
 // One Luminaria message per reply: its tool steps (grouped, plain English) and its text share one heading.
 let turn=null,group=null;
 for(const m of messages){
  if(m.role==='tool')continue;
  let text=typeof m.content==='string'?m.content:(m.content||[]).filter(p=>p.type==='text').map(p=>p.text).join('\n');
  let el;
  if(m.role==='assistant'&&turn&&!m.checkpoint){el=turn}
  else{
   el=document.createElement('article');el.className='message '+m.role+(m.checkpoint?' checkpoint':'');
   el.innerHTML=`<div class="message-heading">${m.role==='assistant'?'<img src="/brand/luminaria.png" alt="" width="20" height="20">':''}<strong>${m.role==='user'?'You':'Luminaria'}</strong><span>${new Date(m.created*1000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</span></div>`;
   $('#messages').append(el);turn=m.role==='assistant'?el:null;group=null;
  }
  if(m.reasoning){const r=document.createElement('details');r.innerHTML=`<summary>Reasoning</summary><pre>${esc(m.reasoning)}</pre>`;el.append(r)}
  if(text.trim()){const body=document.createElement('div');body.className='markdown';body.innerHTML=markdown(text);el.append(body);group=null;decorateMarkdown(body)}
  if(m.hidden_code?.length){const d=document.createElement('details');d.className='hidden-code';const lines=m.hidden_code.join('\n').split('\n').length;d.innerHTML=`<summary>Code it used (${lines} line${lines===1?'':'s'})</summary>`+m.hidden_code.map(c=>`<pre>${esc(c)}</pre>`).join('');el.append(d)}
  for(const c of m.tool_calls||[]){
   const action=(state.actions||[]).find(a=>a.call_id===c.id)||(state.actions||[]).find(a=>a.name===c.function.name&&JSON.stringify(a.args)===JSON.stringify(parseArgs(c.function.arguments)));
   if(!group){group=stepGroup();el.append(group.el)}
   group.add(c,action);
  }
  if(Array.isArray(m.content))for(const p of m.content.filter(p=>p.type==='image_ref')){const img=document.createElement('img');img.className='chat-image';img.alt='Attached image';el.append(img);loadImage(p.id,img)}
  if(summaries.has(m.id)){const marker=document.createElement('div');marker.className='compaction-marker';marker.innerHTML=icon('compress')+'<span>Context compacted · original history preserved</span>';$('#messages').append(marker);turn=null;group=null}
 }
 const run=state.run;$('#live-message').hidden=!active();$('#live-phase').textContent=run?.phase||'';$('#working-label').textContent=run?.phase||'';$('#live-content').innerHTML=markdown(run?.live||'');$('#live-reasoning').hidden=!run?.reasoning_text;$('#live-reasoning pre').textContent=run?.reasoning_text||'';
 $('#send').hidden=false;$('#send').title=active()?'Queue message':'Send message';$('#stop').hidden=!active();$('#prompt').disabled=false;$('#attach-button').disabled=active();$('#reasoning').disabled=active();$('#plan-only').disabled=active();
 const undoable=!active()&&state.changes?.undoable?state.changes:null;$('#run-status').hidden=!run&&!state.plan?.steps?.length&&!undoable;$('#run-status').innerHTML=(run?`${esc(run.phase)}${run.metrics?.tokens_per_second?' · '+run.metrics.tokens_per_second+' tok/s (end-to-end)':''}${run.resume_available?' <button class="text-button" id="resume-run">Resume task</button>':''}${run.checkpoint&&run.finished?` · <button class="text-button" id="continue-run">Continue task</button>`:''}${planReady(run)?` · Plan ready${run.plan_version?'':' (no plan was recorded)'} <button class="text-button" id="carry-out-plan">Carry out plan</button><button class="text-button" id="revise-plan">Revise plan</button>`:''}${run.compact_result?.reason?' · '+esc(run.compact_result.reason):''}`:'')+(state.plan?.steps?.length?`${run?' · ':''}<button class="text-button" id="view-plan">View plan (${state.plan.steps.filter(x=>x.status==='done').length}/${state.plan.steps.length})</button>${!active()&&state.plan.steps.some(x=>x.status==='blocked'||x.status==='done')&&state.plan.steps.some(x=>!['done','skipped'].includes(x.status))?' <button class="text-button" id="continue-plan">Continue plan</button>':''}`:'')+(undoable?`${run||state.plan?.steps?.length?' · ':''}<button class="text-button" id="undo-changes" title="Put back the files the last task changed">Undo file changes (${undoable.undoable})</button>`:'');
 if($('#continue-run'))$('#continue-run').onclick=safe(async()=>{$('#continue-run').disabled=true;await api('/chats/'+chat+'/continue','POST');await refresh()});
 if($('#resume-run'))$('#resume-run').onclick=safe(async()=>{await api('/chats/'+chat+'/resume','POST');await refresh()});
 if($('#carry-out-plan'))$('#carry-out-plan').onclick=safe(async()=>{$('#plan-only').checked=false;window.luminariaQueue.enqueue(chat,{text:'Carry out the saved plan, one step at a time.',attachments:[],reasoning:$('#reasoning').checked,plan_only:false,plan_run:true})});
 if($('#undo-changes'))$('#undo-changes').onclick=safe(openUndo);
 if($('#continue-plan'))$('#continue-plan').onclick=safe(async()=>{$('#plan-only').checked=false;window.luminariaQueue.enqueue(chat,{text:'Continue the plan from the step that stopped.',attachments:[],reasoning:$('#reasoning').checked,plan_only:false,plan_run:true})});
 if($('#view-plan'))$('#view-plan').onclick=safe(openPlan);
 if($('#revise-plan'))$('#revise-plan').onclick=()=>{$('#plan-only').checked=true;$('#prompt').focus()};
 const pending=(state.actions||[]).filter(a=>a.status==='pending');$('#pending-approvals').innerHTML=pending.map(a=>`<div class="approval"><div class="approval-head">${icon('lock')}<strong>Allow ${esc(a.name.replace('__',' · '))}?</strong></div><pre>${esc(JSON.stringify(a.args,null,2))}</pre><div class="approval-footer"><span>${a.tier==='always'?'Always asks · this action only':'Review before execution'}</span><button class="btn" data-decision="deny" data-action="${a.id}">Deny</button>${a.tier==='approve'?`<button class="btn" data-decision="allow" data-scope="always" data-action="${a.id}">Always allow</button>`:''}<button class="btn primary" data-decision="allow" data-action="${a.id}">Allow once</button></div></div>`).join('');
 $$('[data-decision]').forEach(b=>b.onclick=safe(async()=>{b.disabled=true;await api('/approvals/'+b.dataset.action+'/decision','POST',{decision:b.dataset.decision,scope:b.dataset.scope||'once'});await refresh()}));
 const ctx=run?.context?.used?run.context:state.context||{};const limit=ctx.limit||state.context_limit||32768;$('#context-value').textContent=`${ctx.used?Math.round(ctx.used/100)/10+'k':'0'} / ${Math.round(limit/1024)}k`;$('#context-fill').style.width=(100*(ctx.used||0)/limit)+'%';$('#context-fill').classList.toggle('warning',(ctx.used||0)/limit>.8);$('#context-caption').textContent=ctx.used?`${(ctx.reserved||4096).toLocaleString()} tokens reserved for output. ${state.summaries?.length||0} compactions saved.`:'History is saved. Context compacts automatically.';$('#compact').disabled=active()||!messages.length;
 $('#activity-count').textContent=state.actions?.length||'';renderInspector();
