async function events(){for(;;){try{const r=await fetch('/api/events',{headers:{'X-Studio-Token':token}});if(!r.ok)throw Error('Stream disconnected');const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='';for(;;){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let end;while((end=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,end);buffer=buffer.slice(end+2);for(const line of block.split('\n'))if(line.startsWith('data: ')){const e=JSON.parse(line.slice(6));if(e.type==='work'){window.dispatchEvent(new CustomEvent('studio-work',{detail:e.event}));continue}if(e.type==='ready')window.dispatchEvent(new Event('studio-work-reconnect'));if(e.type==='model_recovering')toast('The model manager had stopped. Restarting it and retrying…');if(e.type==='model_state')safe(health)();if(['delta','token','reasoning'].includes(e.type)&&e.chat===chat){if(state.run){if(e.type==='reasoning')state.run.reasoning_text=(state.run.reasoning_text||'')+e.text;else state.run.live=(state.run.live||'')+e.text;$('#live-content').innerHTML=markdown(state.run.live||'');$('#live-reasoning').hidden=!state.run.reasoning_text;$('#live-reasoning pre').textContent=state.run.reasoning_text||'';const sc=$('#messages-scroll');if(sc.scrollHeight-sc.scrollTop-sc.clientHeight<150)sc.scrollTop=sc.scrollHeight;window.dispatchEvent(new Event('mint-token'))}}else scheduleRefresh()}}}}catch{}await new Promise(r=>setTimeout(r,1500));try{token=(await fetch('/api/bootstrap').then(r=>r.json())).token;await refresh();window.dispatchEvent(new Event('studio-work-reconnect'))}catch{}}}
