 // Files reach the chat three ways: the Windows dialog and drops give full paths (nothing is copied, any size);
 // a browser file without a path is uploaded (up to 25 MB).
 async function attachPaths(body){const r=await api('/attachments/path','POST',body);for(const a of r.attachments){if(attachments.length>=ATTACH_LIMIT){toast(`Attach at most ${ATTACH_LIMIT} items per message.`);break}attachments.push(a)}renderAttachments();return r.attachments.length}
